// Rust 变量与可变性示例
// 运行：rustc variables.rs && ./variables
// 或：cargo new variables && 把 main 函数放进去

// 常量：全大写下划线命名，必须显式标注类型，可在模块任意位置定义
const MAX_SCORE: u32 = 100;

fn main() {
    // 1. 默认不可变绑定：声明后不能再赋值
    let score = 86; // 编译器推断为 i32
    println!("初始分数：{score}");
    // score = 90; // ❌ 编译错误：cannot assign twice to immutable variable

    // 2. 需要被修改时，用 mut 显式声明可变性
    let mut bonus = 5;
    bonus += 3;
    println!("加分后的 bonus：{bonus}"); // 8

    // 3. 变量遮蔽（shadowing）：用 let 重新绑定同名变量，可以改变类型
    let total = score + bonus; // i32
    let total = format!("总分：{total} / {MAX_SCORE}"); // 现在 total 是 String
    println!("{total}");

    // 4. 遮蔽常用于「同一份语义的形态转换」，避免发明冗长的变量名
    let input = "  42  ";
    let input = input.trim(); // &str：去掉首尾空白
    let input: i32 = input.parse().expect("解析失败"); // i32
    println!("解析结果：{input}");

    // 5. 遮蔽与作用域：内层作用域的同名绑定在块结束时消失
    {
        let total = 1_000; // 仅在本块可见，字面量中的下划线是视觉分隔符
        println!("块内 total：{total}");
    }
    println!("块外 total：{total}"); // 仍然是 String 版本的 total

    // 6. 类型标注与数值字面量
    let age: u8 = 30;
    let pi = 3.14; // 默认 f64
    let big = 1_000_000u64; // 字面量后缀指定类型
    println!("age={age}, pi={pi}, big={big}");
}

